import "./button.css";
import { Btn } from "@/registry/p1/internal/btn";

export interface ButtonProps {
  label: string;
  href: string;
  variant: "primary" | "secondary" | "yellow" | "purple";
  align: "left" | "center";
}

export function Button({ label, href, variant, align }: ButtonProps) {
  return (
    <div className="p1-button p1-block" data-align={align}>
      <Btn href={href} variant={variant}>
        {label}
      </Btn>
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta } from '../define-meta';
import { Button, type ButtonProps } from "./button";
export type { ButtonProps };

export const ButtonBlock: ComponentConfig<ButtonProps> = {
  fields: {
    label: {
      type: "text" as const,
      ai: {
        instructions:
          "Call-to-action label. 2–5 words, imperative verb first. Example: 'Get started free', 'Learn more'. No trailing punctuation.",
      },
    },
    href: {
      type: "text" as const,
      ai: { exclude: true },
    },
    variant: {
      type: "select" as const,
      options: [
        { label: "Primary", value: "primary" },
        { label: "Secondary", value: "secondary" },
        { label: "Yellow", value: "yellow" },
        { label: "Purple", value: "purple" },
      ],
    },
    align: {
      type: "radio" as const,
      options: [
        { label: "Left", value: "left" },
        { label: "Center", value: "center" },
      ],
    },
  },
  defaultProps: {
    label: "Get started",
    href: "#",
    variant: "primary",
    align: "left",
  },
  render: Button,
};

export const meta = defineMeta({
  title: 'Button',
  description: 'Single CTA button (primary/secondary/yellow/purple) centered or left-aligned; use to place a standalone call-to-action.',
  categories: ["content"],
  published: true,
  registryDependencies: ["@p1/tokens","@p1/internal-btn"],
});

.p1-button {
  display: flex;
}

.p1-button[data-align="left"] {
  justify-content: flex-start;
}

.p1-button[data-align="center"] {
  justify-content: center;
}

